fn polyline(off: i8, scl: i8) -> [i8; 2] {
    // The polynomial is P(x) = c + m·x
    // where c = off and m = scl.
    // We return [c, m] so that P(1) = off + scl (interpreted mathematically).
    [off, scl]
}

fn main() {
    // Example usage
    let coeffs = polyline(10, -3);
    assert_eq!(coeffs, [10, -3]);
    // P(x) = 10 - 3x, so P(1) = 7
    let value_at_1 = coeffs[0].wrapping_add(coeffs[1]);
    assert_eq!(value_at_1, 7);
    println!("P(x) = {} + {}·x", coeffs[0], coeffs[1]);
}